import React, { useState } from 'react';
// import './Navbar.css';
const Navbar = () => {
  const [cartCount, setCartCount] = useState(0);
  return (
    <nav className="navbar" role="navigation" style={{ backgroundColor: '#c0a6a6', color: '#000000 !important' }}>
      <div className="navbar-left">
        <a href="/" className="logo">ShopNow</a>
      </div>
      <div className="navbar-center">
        <ul className="nav-links">
          <li><a  href="/products">Products</a></li>
          <li><a className="text-decoration-none" href="/about">About Us</a></li>
          <li><a className="text-decoration-none" href="/contact">Contact</a></li>
        </ul>
      </div>
      <div className="navbar-right">
        <a href="/cart" className="cart-icon" aria-label="Shopping Cart">
          <i className="fas fa-shopping-cart"></i>
          <button className='btn-solid' onClick={() => setCartCount(count => count + 1)}>
            Add to Cart
          </button>
          <span className="cart-count" >{cartCount}</span>
        </a>
        <a href="/account" className="user-icon" aria-label="User Account">
          <i className="fas fa-user"></i>
        </a>
      </div>
    </nav>
  );
};
export default Navbar;
